HashSet<String> gatherUsedTypeNames() {
	HashSet<String> usedNames = new HashSet<String>();

	JCClassDecl td = null;
	if (parentType != null) {
		String typeName = parentType.getName();
		if (typeName != null) usedNames.add(typeName);
		JCTree raw = parentType.get();
		if (raw instanceof JCClassDecl) td = (JCClassDecl) raw;
	}

	List<JCTypeParameter> classTypeParams = td == null ? null : td.typarams;
	List<JCTypeParameter> params = typeParams != null ? typeParams : classTypeParams;
	if (params != null) {
		for (JCTypeParameter typeParam : params) {
			if (typeParam.getName() != null) usedNames.add(typeParam.getName().toString());
		}
	}

	if (td != null && td.name != null) {
		usedNames.add(td.name.toString());
	}

	if (td != null) {
		for (JCTree member : td.getMembers()) {
			if (member.getKind() == com.sun.source.tree.Tree.Kind.VARIABLE && member instanceof JCVariableDecl) {
				JCVariableDecl field = (JCVariableDecl) member;
				if (field.name == null) continue;
				JCTree type = field.getType();
				if (type instanceof JCIdent) {
					usedNames.add(type.toString());
				}
			}
		}
	}

	return usedNames;

